import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useSelector } from 'react-redux';
import { Row, Col, Label, FormGroup } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import constants from 'config/constants';
import { fetchAnnouncementImageBlobApi } from 'actions/admin/students';

export const MAX_IMAGE_MB = 10;

// Only admins and teachers can attach a photo to a notice / circular.
export const useCanAttachImage = () => {
  const role = useSelector(state => state.auth.loggedUserRole);
  return role === constants.roles.admin || role === constants.roles.teacher;
};

// -> error text, or '' when the file can go in.
const validateImage = file => {
  if (!/^image\//.test(file.type)) return `${file.name} is not an image`;
  if (file.size > MAX_IMAGE_MB * 1024 * 1024) return `${file.name} is larger than ${MAX_IMAGE_MB} MB`;
  return '';
};

// Photos are read once per id and kept for the session (the list and the detail pane both show the same one).
const blobUrls = new Map();
const loadBlobUrl = (dbFileId, token) => {
  if (!blobUrls.has(dbFileId)) {
    const request = fetchAnnouncementImageBlobApi({ dbFileId, token })
      .then(res => URL.createObjectURL(res.data))
      .catch(err => {
        blobUrls.delete(dbFileId);
        throw err;
      });
    blobUrls.set(dbFileId, request);
  }
  return blobUrls.get(dbFileId);
};

// The photo of a notice / circular. `fit` is 'cover' for thumbnails, 'contain' to show the whole photo.
export const AnnouncementImage = ({ dbFileId, alt = 'Photo', fit = 'cover', style }) => {
  const token = useSelector(state => state.auth.loggedUserToken);
  const [src, setSrc] = useState(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setSrc(null);
    setFailed(false);
    loadBlobUrl(dbFileId, token)
      .then(url => !cancelled && setSrc(url))
      .catch(() => !cancelled && setFailed(true));
    return () => {
      cancelled = true;
    };
  }, [dbFileId, token]);

  const box = { background: '#f1ecf5', color: colors.grey3, fontSize: 11, ...style };
  if (failed)
    return <div style={{ ...box, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>No photo</div>;
  if (!src) return <div style={box} />;
  return <img src={src} alt={alt} style={{ ...box, objectFit: fit, display: 'block' }} />;
};

// The "add a photo" field of the notice / circular forms. `file` is the chosen image (or null).
export const AnnouncementImagePicker = ({ file, onChange, disabled }) => {
  const inputRef = useRef(null);
  const [error, setError] = useState('');
  const preview = useMemo(() => (file ? URL.createObjectURL(file) : null), [file]);
  useEffect(() => () => preview && URL.revokeObjectURL(preview), [preview]);

  const pick = event => {
    const chosen = event.target.files?.[0];
    event.target.value = '';
    if (!chosen) return;
    const problem = validateImage(chosen);
    setError(problem);
    if (!problem) onChange(chosen);
  };

  return (
    <div>
      <input ref={inputRef} type="file" accept="image/*" hidden onChange={pick} />
      {preview ? (
        <div style={{ position: 'relative', display: 'inline-block' }}>
          <img
            src={preview}
            alt="Selected"
            style={{ maxWidth: '100%', maxHeight: 200, borderRadius: 8, border: '1px solid #EDE1F7', display: 'block' }}
          />
          <button
            type="button"
            aria-label="Remove photo"
            disabled={disabled}
            onClick={() => {
              setError('');
              onChange(null);
            }}
            style={{
              position: 'absolute',
              top: 6,
              right: 6,
              width: 24,
              height: 24,
              lineHeight: '22px',
              padding: 0,
              border: 'none',
              borderRadius: '50%',
              background: 'rgba(0,0,0,0.65)',
              color: '#fff',
              cursor: 'pointer',
            }}>
            &times;
          </button>
        </div>
      ) : (
        <>
          <CustomButton
            type="button"
            size="small"
            variant="outlined"
            name="Add photo"
            disabled={disabled}
            onClick={() => inputRef.current.click()}
          />
          <span style={{ fontSize: 12, color: '#9a9a9a', marginLeft: 8 }}>One image, up to {MAX_IMAGE_MB} MB</span>
        </>
      )}
      {!!error && <div className="err-msg">{error}</div>}
    </div>
  );
};

// The picker as a form row; renders nothing for roles that cannot attach a photo.
export const AnnouncementImageField = props => {
  const canAttach = useCanAttachImage();
  if (!canAttach) return null;
  return (
    <Row>
      <Col sm={12}>
        <FormGroup>
          <Label htmlFor="">Photo</Label>
          <AnnouncementImagePicker {...props} />
        </FormGroup>
      </Col>
    </Row>
  );
};
